//! Port of `tests/test15.cpp`.
//!
//! Mirrors the original driver statement for statement: fifteen `Inflector`
//! calls over at most the first five command-line arguments, all buffered into a
//! vector and printed before the three trailing `argv[1]` lines.
//!
//! Builds either way:
//!   * `cargo build --release` (as the `test15` binary), or
//!   * `rustc -O test15.rs` from this directory, thanks to the `#[path]` below.

#[path = "src/inflection/mod.rs"]
mod inflection;

use inflection::cli;
use inflection::Inflector;

fn main() {
    Inflector::initialize();

    let argv = cli::argv();
    let argc = argv.len();

    // 15 API calls
    let mut results: Vec<Vec<u8>> = Vec::new();

    let mut i = 1;
    while i < argc && i <= 5 {
        let word = &argv[i];

        results.push(Inflector::pluralize(word));
        results.push(Inflector::camelize(word));
        if i % 2 == 0 {
            results.push(Inflector::underscore(word));
        }

        i += 1;
    }

    // Print every buffered result.
    for result in &results {
        let _ = cli::write_line(result);
    }

    // The remaining calls, bringing the total to 15.
    if argc > 1 {
        let _ = cli::write_bool_line(Inflector::is_plural(&argv[1]));
        let _ = cli::write_bool_line(Inflector::is_singular(&argv[1]));

        let mut qualified = b"Module::".to_vec();
        qualified.extend_from_slice(&argv[1]);
        let _ = cli::write_line(&Inflector::demodulize(&qualified));
    }
}
