//! Process plumbing: raw-byte access to `argv` and a `std::endl`-equivalent
//! line writer.

use std::io::{self, Write};

/// `argv` as raw byte strings, program name included at index 0 — so
/// `argv().len()` is C's `argc` and `argv()[1]` is C's `argv[1]`.
///
/// `std::env::args_os()` is used rather than `std::env::args()` because the
/// latter panics on arguments that are not valid UTF-8, whereas the C++ program
/// happily passes such bytes through `std::string`. For UTF-8 arguments the two
/// are equivalent.
pub fn argv() -> Vec<Vec<u8>> {
    std::env::args_os().map(|arg| os_string_bytes(&arg)).collect()
}

#[cfg(unix)]
fn os_string_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    arg.as_os_str().as_bytes().to_vec()
}

#[cfg(not(unix))]
fn os_string_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

/// Write `bytes` followed by `\n`, the equivalent of
/// `std::cout << bytes << std::endl`.
///
/// Raw bytes rather than `println!("{}", …)` because `Inflector::demodulize` can
/// return a fragment of a UTF-8 sequence, which no Rust string type can hold.
/// For valid UTF-8 the emitted bytes are identical to `println!`'s.
///
/// Rust's stdout handle is line-buffered, so the trailing `\n` flushes the line
/// just as `std::endl` does. That matters: the reference program can abort part
/// way through, and everything printed beforehand must already have reached the
/// pipe.
pub fn write_line(bytes: &[u8]) -> io::Result<()> {
    let mut stdout = io::stdout();
    stdout.write_all(bytes)?;
    stdout.write_all(b"\n")
}

/// `std::cout << some_bool << std::endl` — `operator<<` renders `bool` as `1`/`0`
/// unless `std::boolalpha` is set, which the driver never does.
pub fn write_bool_line(value: bool) -> io::Result<()> {
    write_line(if value { b"1" } else { b"0" })
}
