//! Small pieces of `std::string` semantics that the port has to reproduce
//! exactly, including one failure mode.
//!
//! `Inflector::demodulize` is implemented in the original as a `rfind` followed
//! by `substr`. For some inputs the computed offset runs past the end of the
//! string, and `std::string::substr` then throws `std::out_of_range`. Nothing
//! catches it, so the C++ program dies via `std::terminate` -> `abort()`: the
//! runtime prints a fixed two-line diagnostic on stderr and the process is
//! killed by `SIGABRT` (shell status 134). Any stdout already written has been
//! flushed by then, because the driver uses `std::endl`.
//!
//! `substr_from` reproduces all of that.

use std::io::{self, Write};

/// `std::string::rfind(char)` — byte offset of the last occurrence.
#[inline]
pub fn rfind_byte(haystack: &[u8], needle: u8) -> Option<usize> {
    haystack.iter().rposition(|byte| *byte == needle)
}

/// `s.substr(pos)` — the tail of `s` starting at byte offset `pos`.
///
/// `pos == s.len()` is legal and yields the empty string; `pos > s.len()` is the
/// `std::out_of_range` case and terminates the process exactly as the C++
/// program does.
#[inline]
pub fn substr_from(s: &[u8], pos: usize) -> &[u8] {
    if pos > s.len() {
        terminate_substr_out_of_range(pos, s.len());
    }
    &s[pos..]
}

/// Reproduce libstdc++'s uncaught-exception death for `substr`.
///
/// The message text and the `SIGABRT` exit are byte-identical to the reference
/// binary's, which was captured as:
///
/// ```text
/// terminate called after throwing an instance of 'std::out_of_range'
///   what():  basic_string::substr: __pos (which is 9) > this->size() (which is 8)
/// ```
fn terminate_substr_out_of_range(pos: usize, size: usize) -> ! {
    // std::endl already flushed every stdout line the driver produced; make sure
    // the same is true here before the abort discards buffers.
    let _ = io::stdout().flush();

    let mut stderr = io::stderr();
    let _ = stderr.write_all(
        b"terminate called after throwing an instance of 'std::out_of_range'\n",
    );
    let _ = stderr.write_all(
        format!(
            "  what():  basic_string::substr: __pos (which is {pos}) \
             > this->size() (which is {size})\n"
        )
        .as_bytes(),
    );
    let _ = stderr.flush();

    // Raises SIGABRT, matching `std::terminate` (shell exit status 134).
    std::process::abort()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rfind_finds_the_last_match() {
        assert_eq!(rfind_byte(b"Module::cat", b':'), Some(7));
        assert_eq!(rfind_byte(b"Module::a:b", b':'), Some(9));
        assert_eq!(rfind_byte(b"nocolon", b':'), None);
        assert_eq!(rfind_byte(b"", b':'), None);
    }

    #[test]
    fn substr_at_end_is_empty() {
        assert_eq!(substr_from(b"abc", 3), b"");
        assert_eq!(substr_from(b"abc", 1), b"bc");
    }
}
