use strict; use warnings;
use POSIX ":sys_wait_h";

my $CPP  = '/workspace/dataset/test15_executable';
my $RUST = '/output/test15';

sub run_prog {
    my ($bin, @args) = @_;
    my $of = "/tmp/sep/.o.$$"; my $ef = "/tmp/sep/.e.$$";
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $of) or POSIX::_exit(127);
        open(STDERR, '>', $ef) or POSIX::_exit(127);
        exec($bin, @args) or POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    local $/; 
    open(my $oh, '<', $of); binmode $oh; my $out = <$oh> // ''; close $oh;
    open(my $eh, '<', $ef); binmode $eh; my $err = <$eh> // ''; close $eh;
    unlink $of, $ef;
    return ($st, $out, $err);
}

sub hex_of { my $s = shift; return unpack("H*", $s); }
sub status_str {
    my $st = shift;
    my $sig = $st & 127; my $code = $st >> 8; my $core = ($st & 128) ? 1 : 0;
    return $sig ? "signal=$sig core=$core" : "exit=$code";
}

my $pass = 0; my $fail = 0; my @fails;
sub diffcase {
    my @args = @_;
    my ($cs,$co,$ce) = run_prog($CPP, @args);
    my ($rs,$ro,$re) = run_prog($RUST, @args);
    if ($cs == $rs && $co eq $ro && $ce eq $re) { $pass++; return 1; }
    $fail++;
    push @fails, sprintf("ARGS=%s\n  cpp : %s out=%s err=%s\n  rust: %s out=%s err=%s",
        join(' ', map { "<".unpack("H*",$_).">" } @args),
        status_str($cs), hex_of($co), hex_of($ce),
        status_str($rs), hex_of($ro), hex_of($re));
    return 0;
}

# ---------------- case generation ----------------
my @cases; my %seen;
sub add { my @a=@_; my $k = join("\0", scalar(@a), @a); return if $seen{$k}++; push @cases, [@a]; }

sub prod {
    my ($alpha, $maxlen) = @_;
    my @out = ('');
    my @cur = ('');
    for my $n (1..$maxlen) {
        my @next;
        for my $p (@cur) { for my $c (@$alpha) { push @next, $p.$c; } }
        push @out, @next; @cur = @next;
    }
    return @out;
}

my @A = ('a','B','_');
my @famA = prod(\@A, 5);                      # 364
my @B5 = ('a','B','_','-',' ');
my @famB = prod(\@B5, 4);                     # 781
my @FULL = ('a','B','_','-',' ','.','/',':','0','9',"\t");
my @famC = prod(\@FULL, 2);                   # 133

srand(20260808);
my @famD;
for (1..2200) { my $n = 3 + int(rand(12)); my $s=''; $s .= $FULL[int(rand(scalar @FULL))] for (1..$n); push @famD, $s; }

my @famE;
my @seps = ('_','-',' ','.','/',':',"\t");
my @cores = ('a','B','ab','aB','Ba','BB','aa','Hello','World','xY','','9','0','A','z','Zz');
for my $s (@seps) { for my $r (1..8) { my $run = $s x $r;
    for my $c (@cores) { push @famE, $run.$c, $c.$run, $run.$c.$run, $c.$run.$c; } } }
push @famE, '_' x 40, ('_' x 40).'a', 'a'.('_' x 40).'B', ('_a' x 20), ('a_' x 20), ('_B' x 20),
            ('B' x 30), '_'.('B' x 30), ("\t" x 10).'B', ('_' x 3).('B' x 3).('_' x 3),
            ('aB_' x 5), ('_-_' x 6).'B', (' ' x 12).'B', 'B'.(' ' x 12), ('.' x 5).'B'.('.' x 5);

my @WIDE = split //, "aAbBzZ_-. /:09\t\x0b\x0c\r\x7f\@[]^`{|~\$";
my @famF;
for (1..700) { my $n = 1 + int(rand(12)); my $s=''; $s .= $WIDE[int(rand(scalar @WIDE))] for (1..$n); push @famF, $s; }

my @all = (@famA, @famB, @famC, @famD, @famE, @famF);
for my $w (@all) { add('dummy', $w); }
# same word at even position 4 (underscore) with junk in between
for my $w (@famA[0..119], @famB[0..119], @famE[0..119]) { add('dummy','x','y',$w); }
# word at arg1 (skip empty / trailing ':' -> designed abort)
for my $w (@famA, @famB[0..249]) { next if $w eq '' || substr($w,-1) eq ':'; add($w, 'dummy'); }
# words at positions 2 and 4 simultaneously
for my $i (0..199) { add('dummy', $famA[$i % scalar(@famA)], 'z', $famB[($i*7) % scalar(@famB)]); }

printf STDERR "cases=%d (A=%d B=%d C=%d D=%d E=%d F=%d)\n", scalar(@cases), scalar(@famA), scalar(@famB), scalar(@famC), scalar(@famD), scalar(@famE), scalar(@famF);

my $n=0;
for my $c (@cases) { diffcase(@$c); $n++; printf STDERR "  ..%d done (pass=%d fail=%d)\n", $n, $pass, $fail if $n % 1000 == 0; }
